import React from 'react';

import PohList from '@ui-kit/List';

import { IBaseHiking } from '../../@types/hikingList.types';
import HikingBadge from '../HikingBadge';

interface IHikingBaseListProps {
  list: IBaseHiking[];
  onSelect: (selectedHiking: IBaseHiking, e: React.MouseEvent) => void;
}

const HikingBaseList: React.FC<IHikingBaseListProps> = ({ list, onSelect }) => {
  return (
    <div>
      <PohList
        data={list.map((d) => {
          return {
            key: d.id,
            onClick: (e) => onSelect(d, e),
            action: true,
            children: <HikingBadge hiking={d} />,
            className: 'px-2 py-2',
          };
        })}
      />
    </div>
  );
};

export default HikingBaseList;
